class Solution {
  public long minInitialStrength(int[] monsters, int[][] boosts) {
    int n = monsters.length;
    long[] diff = new long[n + 1];
    for (int[] b : boosts) {
      diff[b[0]] += b[2];
      diff[b[1] + 1] -= b[2];
    }
    long[] bonus = new long[n];
    long run = 0;
    for (int i = 0; i < n; i++) {
      run += diff[i];
      bonus[i] = run;
    }
    long required = 0;
    for (int i = n - 1; i >= 0; i--) {
      long need = Math.max(0, monsters[i] - bonus[i]);
      long carry = required > 0 ? required + monsters[i] : 0;
      required = Math.max(need, carry);
    }
    return required;
  }
}
